import { callLLM } from './llm';
import { fetchCompanyNewsAndFacts } from './search';
import { InvestmentReport, PipelineProgress } from '../types';

export type ProgressCallback = (progress: PipelineProgress) => void;

/**
 * Orchestrates the Investment Research Graph pipeline.
 * Simulates a LangGraph state graph.
 * Executes the following specialized nodes sequentially:
 * 1. Company Understanding
 * 2. Financial Research
 * 3. Competitive Landscape
 * 4. News & Sentiment
 * 5. Risk Assessment
 * 6. Bull vs Bear Debate
 * 7. Contradiction & Missing Info Detector
 * 8. AI Final Decision
 */
export async function runResearchPipeline(
  companyName: string,
  onProgress?: ProgressCallback
): Promise<InvestmentReport> {
  const logProgress = (stage: PipelineProgress['stage'], message: string) => {
    console.log(`[Pipeline Progress - ${stage}]: ${message}`);
    if (onProgress) {
      onProgress({ stage, message });
    }
  };

  // Step 1: Company Understanding
  logProgress('company', `Analyzing core business of "${companyName}"...`);
  const companyPrompt = `
    You are the Company Understanding Agent. Research the company "${companyName}".
    Identify the company name, ticker symbol, industry sector, key products or services, business model, and write a high-level summary.
    Return JSON format only:
    {
      "name": "string",
      "ticker": "string",
      "industry": "string",
      "products": ["string"],
      "businessModel": "string",
      "summary": "string"
    }
  `;
  const companyRes = await callLLM(companyPrompt, "You are a professional business research analyst.");
  const companyData = JSON.parse(companyRes.text);

  // Step 2: Financial Research
  logProgress('financials', `Analyzing revenue trends and margins for ${companyData.name}...`);
  const financialsPrompt = `
    You are the Financial Research Agent. Research the financials for "${companyData.name}".
    Analyze revenue trends, profitability indicators, operational margins, debt levels, cash flow, and growth metrics.
    Also compute scores (values from 1 to 100) for growth, profitability, stability, innovation, and market position.
    Return JSON format only:
    {
      "revenueTrends": "string",
      "profitability": "string",
      "margins": "string",
      "debtLevel": "string",
      "cashFlow": "string",
      "growthIndicators": "string",
      "scores": {
        "growth": number,
        "profitability": number,
        "stability": number,
        "innovation": number,
        "marketPosition": number
      }
    }
  `;
  const financialsRes = await callLLM(financialsPrompt, "You are an expert financial auditor.");
  const financialsData = JSON.parse(financialsRes.text);

  // Step 3: Competitive Landscape
  logProgress('competition', `Evaluating competitive landscape and moat for ${companyData.name}...`);
  const competitionPrompt = `
    You are the Competitive Landscape Agent. Analyze the competition for "${companyData.name}".
    Identify primary competitors, market position, structural moats (switching costs, network effects, scale, etc.), and immediate threats.
    Return JSON format only:
    {
      "competitors": ["string"],
      "marketPosition": "string",
      "moat": "string",
      "threats": ["string"]
    }
  `;
  const competitionRes = await callLLM(competitionPrompt, "You are a strategic industry analyst.");
  const competitionData = JSON.parse(competitionRes.text);

  // Step 4: News & Sentiment
  logProgress('news', `Scanning recent headlines and sentiment analysis for ${companyData.name}...`);
  const externalNews = await fetchCompanyNewsAndFacts(companyData.name);
  const newsPrompt = `
    You are the News & Sentiment Agent. Review this recent news and analyze sentiment for "${companyData.name}".
    News context: ${JSON.stringify(externalNews)}
    List recent news headlines, controversies, positive developments, and provide a sentiment summary.
    Return JSON format only:
    {
      "recentNews": [
        { "title": "string", "date": "string", "sentiment": "positive | negative | neutral" }
      ],
      "controversies": ["string"],
      "developments": ["string"],
      "sentimentSummary": "string"
    }
  `;
  const newsRes = await callLLM(newsPrompt, "You are a real-time sentiment analyst.");
  const newsData = JSON.parse(newsRes.text);

  // Step 5: Risk Assessment
  logProgress('risks', `Evaluating regulatory, execution, and technology risks...`);
  const risksPrompt = `
    You are the Risk Agent. Analyze risks for "${companyData.name}".
    Assess regulatory, macroeconomic, execution, and technology risks. Calculate an overall risk score (1-100).
    Return JSON format only:
    {
      "regulatory": "string",
      "macroeconomic": "string",
      "execution": "string",
      "technology": "string",
      "riskScore": number
    }
  `;
  const risksRes = await callLLM(risksPrompt, "You are a quantitative risk management officer.");
  const risksData = JSON.parse(risksRes.text);

  // Step 6: Bull vs Bear Debate
  logProgress('debate', `Initiating analyst debate (Bull vs Bear)...`);
  const debatePrompt = `
    You are the Debate Agent. Initiate a debate on "${companyData.name}".
    Create a Bull Analyst arguing why this is an INVEST, and a Bear Analyst arguing why this is a WATCH or PASS.
    Provide a Judge's Verdict resolving the arguments.
    Return JSON format only:
    {
      "bullCase": {
        "analystName": "string",
        "arguments": ["string"],
        "conclusion": "string"
      },
      "bearCase": {
        "analystName": "string",
        "arguments": ["string"],
        "conclusion": "string"
      },
      "judgeVerdict": "string"
    }
  `;
  const debateRes = await callLLM(debatePrompt, "You are a panel of financial experts and judges.");
  const debateData = JSON.parse(debateRes.text);

  // Step 7: Contradiction & Missing Info Detectors
  logProgress('contradictions', `Scanning for conflicting claims and missing info...`);
  const contradictionsPrompt = `
    Compare the following findings for "${companyData.name}":
    Financials: ${JSON.stringify(financialsData)}
    Competition: ${JSON.stringify(competitionData)}
    News & Risks: ${JSON.stringify(newsData)} ${JSON.stringify(risksData)}
    Debate: ${JSON.stringify(debateData)}

    Detect any conflicts, contradictions, or missing key pieces of information.
    Return JSON format only:
    {
      "contradictions": {
        "conflicts": [
          { "factA": "string", "factB": "string", "sourceA": "string", "sourceB": "string", "resolution": "string" }
        ]
      },
      "missingInfo": {
        "missingFields": ["string"],
        "recommendedSources": ["string"],
        "impactOnVerdict": "string"
      }
    }
  `;
  const contradictionsRes = await callLLM(contradictionsPrompt, "You are an audit and logic checker.");
  const rawAuditData = JSON.parse(contradictionsRes.text);
  const contradictionsData = rawAuditData.contradictions || { conflicts: [] };
  const missingInfoData = rawAuditData.missingInfo || { missingFields: [], recommendedSources: [], impactOnVerdict: '' };

  // Step 8: AI Decision Agent
  logProgress('decision', `Synthesizing final recommendation for ${companyData.name}...`);
  const decisionPrompt = `
    You are the Final AI Decision Agent. Choose recommendation: INVEST, WATCH, or PASS for "${companyData.name}".
    Base your decision on all previous insights:
    Company Summary: ${JSON.stringify(companyData)}
    Financials: ${JSON.stringify(financialsData)}
    Competition: ${JSON.stringify(competitionData)}
    News & Sentiment: ${JSON.stringify(newsData)}
    Risks: ${JSON.stringify(risksData)}
    Debate: ${JSON.stringify(debateData)}
    Contradictions: ${JSON.stringify(contradictionsData)}
    Missing Info: ${JSON.stringify(missingInfoData)}

    Provide a final recommendation, confidence score (1-100), top 5 reasons, top 5 risks, short summary, detailed explanation, sources, and explain why other alternatives were rejected.
    Return JSON format only:
    {
      "recommendation": "INVEST | WATCH | PASS",
      "confidenceScore": number,
      "topReasons": ["string"],
      "topRisks": ["string"],
      "shortSummary": "string",
      "detailedExplanation": "string",
      "sourcesUsed": ["string"],
      "whyAlternativeRejected": "string"
    }
  `;
  const decisionRes = await callLLM(decisionPrompt, "You are a Senior Investment Committee Chairman.");
  const decisionData = JSON.parse(decisionRes.text);

  logProgress('complete', `Analysis complete!`);

  return {
    company: companyData,
    financials: financialsData,
    competition: competitionData,
    news: newsData,
    risks: risksData,
    debate: debateData,
    contradictions: contradictionsData,
    missingInfo: missingInfoData,
    decision: decisionData,
  };
}
