import { NextRequest, NextResponse } from 'next/server';
import { runResearchPipeline } from '../../../services/researchGraph';

export const dynamic = 'force-dynamic';

export async function POST(req: NextRequest) {
  try {
    const { companyName } = await req.json();

    if (!companyName || typeof companyName !== 'string' || companyName.trim() === '') {
      return NextResponse.json(
        { error: 'A valid companyName query parameter is required.' },
        { status: 400 }
      );
    }

    const report = await runResearchPipeline(companyName.trim());

    return NextResponse.json({ report });
  } catch (error: any) {
    console.error('Error executing research pipeline API:', error);
    return NextResponse.json(
      { error: error?.message || 'Internal Server Error' },
      { status: 500 }
    );
  }
}
